import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DIGITS = "0123456789"


def _normalize_email(raw):
    """Return the normalized email, or None if it is not valid."""
    s = raw.strip()
    if "<" in s:
        start = s.find("<")
        end = s.find(">", start + 1)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()

    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "")
            local = local.split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"

    if s.count("@") != 1:
        return None
    local, domain = s.split("@")
    if not local:
        return None
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    return s


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or None if it is not valid."""
    s = raw.lower()
    cuts = [i for i in (s.find(m) for m in ("x", "ext", "#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return None


def _normalize_zip(raw):
    """Return a 5-digit ZIP, or "" if it cannot be normalized."""
    z = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    if re.fullmatch(r"[0-9]{5}", z):
        return z
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _pick(group, field):
    """Pick the value for `field` from the group, following the preference rules."""
    cands = [r for r in group if r[field]]
    # Stable multi-pass sort: lowest priority first, highest priority last.
    cands.sort(key=lambda r: r["idx"])                      # earlier row wins ties
    cands.sort(key=lambda r: r["updated"], reverse=True)    # most recent updated
    cands.sort(key=lambda r: r["source"] != "manual")       # manual first
    return cands[0][field] if cands else ""


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        if email is None and phone is None:
            continue
        records.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "phone": phone,
            "source": row.get("source", "").strip().lower(),
            "tags": {t.strip().lower()
                     for t in re.split(r"[;,]", row.get("tags", ""))
                     if t.strip()},
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Step 2: union-find over matching rows (transitive matching).
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for j, r in enumerate(records):
        if r["email"] is not None:
            if r["email"] in email_seen:
                union(email_seen[r["email"]], j)
            else:
                email_seen[r["email"]] = j
        if r["phone"] is not None and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in phone_seen:
                union(phone_seen[key], j)
            else:
                phone_seen[key] = j

    # Step 3: group rows; order groups by their earliest row.
    groups = {}
    order = []
    for j in range(len(records)):
        root = find(j)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(records[j])

    # Step 4: build one output dict per person.
    result = []
    for root in order:
        g = groups[root]
        tags = set()
        for r in g:
            tags |= r["tags"]
        latest = max(r["updated"] for r in g)
        result.append({
            "first_name": _pick(g, "first_name"),
            "last_name": _pick(g, "last_name"),
            "zip": _pick(g, "zip"),
            "email": _pick(g, "email"),
            "phone": _pick(g, "phone"),
            "source": _pick(g, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in g) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return result
